import json
from pathlib import Path

import numpy as np
import jax
import jax.numpy as jnp


def basic_reduce(x: jnp.ndarray) -> jnp.ndarray:
    return jnp.mean(x, axis=1)


def map_square(x: jnp.ndarray) -> jnp.ndarray:
    return jnp.square(x)


def grad_logistic(data: dict) -> jnp.ndarray:
    x = jnp.asarray(data["x"])
    y = jnp.asarray(data["y"])
    w = jnp.asarray(data["w"])

    def loss_fn(w_in: jnp.ndarray) -> jnp.ndarray:
        logits = x @ w_in
        # Logistic loss with labels in {-1, 1}
        return jnp.mean(jnp.logaddexp(0.0, -y * logits))

    return jax.grad(loss_fn)(w)


def scan_rnn(data: dict) -> jnp.ndarray:
    seq = jnp.asarray(data["seq"])
    init = jnp.asarray(data["init"])
    Wx = jnp.asarray(data["Wx"])
    Wh = jnp.asarray(data["Wh"])
    b = jnp.asarray(data["b"])

    def step(h, x_t):
        h_new = jnp.tanh(x_t @ Wx + h @ Wh + b)
        return h_new, h_new

    _, hs = jax.lax.scan(step, init, seq)
    return hs


def jit_mlp(data: dict) -> jnp.ndarray:
    X = jnp.asarray(data["X"])
    W1 = jnp.asarray(data["W1"])
    b1 = jnp.asarray(data["b1"])
    W2 = jnp.asarray(data["W2"])
    b2 = jnp.asarray(data["b2"])

    def mlp(X_in, W1_in, b1_in, W2_in, b2_in):
        hidden = jnp.maximum(0, X_in @ W1_in + b1_in)
        return hidden @ W2_in + b2_in

    mlp_jit = jax.jit(mlp)
    return mlp_jit(X, W1, b1, W2, b2)


def load_input(path: Path):
    if path.suffix == ".npy":
        return np.load(path)
    if path.suffix == ".npz":
        return dict(np.load(path))
    raise ValueError(f"Unsupported input type: {path}")


def main():
    base = Path(__file__).resolve().parent
    with open(base / "problem.json", "r", encoding="utf-8") as f:
        tasks = json.load(f)

    for task in tasks:
        task_id = task["id"]
        input_path = base / task["input"]
        output_path = base / task["output"]
        data = load_input(input_path)

        if task_id == "basic_reduce":
            result = basic_reduce(jnp.asarray(data))
        elif task_id == "map_square":
            result = map_square(jnp.asarray(data))
        elif task_id == "grad_logistic":
            result = grad_logistic(data)
        elif task_id == "scan_rnn":
            result = scan_rnn(data)
        elif task_id == "jit_mlp":
            result = jit_mlp(data)
        else:
            raise ValueError(f"Unknown task id: {task_id}")

        np.save(output_path, np.array(result))


if __name__ == "__main__":
    main()
